INSERT INTO appstore_listing_localization
    (id, tenant_id, organization_id, listing_id, locale, display_name, subtitle, short_description, full_description, whats_new_summary, keywords_json, created_at, updated_at)
VALUES
    ('loc-app-eval-chinese-eval-en', '100001', '0', 'app-eval-chinese-eval', 'en-US', 'Chinese Knowledge (C-Eval)', '52-discipline Chinese knowledge benchmark', 'C-Eval and CMMLU coverage across 52 disciplines and four difficulty levels, measuring Chinese knowledge and subject reasoning.', 'Chinese Knowledge Evaluation draws on C-Eval (13,948 multiple-choice questions across 52 disciplines and four difficulty levels) and CMMLU, scoring accuracy by humanities, social sciences, STEM and professional exams. It compares DeepSeek-V3.2, GLM-4.7, Qwen3-Max, Kimi K2, Doubao-1.6, GPT-5 and Claude Sonnet 4.5, with per-spec ratings and reviews.', 'First release with C-Eval and CMMLU question banks', '["Chinese Knowledge","C-Eval","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-ridiculous-en', '100001', '0', 'app-eval-ridiculous', 'en-US', 'Ridiculous Logic Stress Test', 'Chinese counter-intuitive reasoning stress test', 'Ridiculous Bar questions probe semantic ambiguity, counter-intuitive traps and common-sense correction.', 'Ridiculous Bar questions are a widely used Chinese stress-test set: prompts look simple but hide semantic ambiguity, counter-intuitive premises and homophone traps. The evaluation scores counter-intuitive traps, semantic ambiguity, common-sense correction and multi-turn follow-ups, and records whether a model is led astray or explains itself coherently, with per-spec ratings and reviews.', 'Added multi-turn follow-ups and lead-astray detection', '["Ridiculous Logic","counter-intuitive reasoning","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-instruction-following-en', '100001', '0', 'app-eval-instruction-following', 'en-US', 'Instruction Following (IFEval)', 'Programmatically verifiable instruction benchmark', 'IFEval verifiable instructions measure format, length, keyword and multi-constraint compliance.', 'Instruction Following Evaluation is built on 541 programmatically verifiable IFEval instructions covering JSON and list formats, word and paragraph length limits, required and forbidden keywords, and multi-constraint combinations. It reports strict compliance and per-dimension scores instead of judging answer quality alone, with per-spec ratings and reviews.', 'Added multi-constraint compliance scoring', '["Instruction Following","IFEval","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-swe-bench-en', '100001', '0', 'app-eval-swe-bench', 'en-US', 'Real Repository Repair (SWE-bench)', 'Real GitHub repository repair benchmark', 'SWE-bench Verified issues measure localization, repair and regression verification in real repositories.', 'Real Repository Repair uses the 500 human-verified GitHub issues in SWE-bench Verified. Models must locate defects in real repositories, change code and pass existing tests. It scores autonomous localization, patch correctness, regression pass rate and minimality, complementing the coding agent board, with per-spec ratings and reviews.', 'First release with the SWE-bench Verified baseline', '["Real Repository Repair","SWE-bench","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-pelican-bike-en', '100001', '0', 'app-eval-pelican-bike', 'en-US', 'Pelican on a Bicycle (SVG Spatial Reasoning)', 'Classic spatial reasoning and SVG generation test', 'The pelican-on-a-bicycle prompt tests spatial understanding and SVG code generation: seated bird, paired wheels, feet on pedals.', 'Originating from Simon Willison pelican riding a bicycle folk test, known in Chinese communities as TiHu Riding a Bicycle. One prompt forbids JavaScript and requires native SVG with animateTransform for a looping animation. It scores object composition, spatial relations, limb continuity and code coherence across GPT-5, Claude Sonnet 4.5, Gemini 2.5 Pro, DeepSeek-V3.2, Qwen3-Max and GLM-4.7, with per-spec ratings and reviews.', 'Added looping animation and pedal continuity checks', '["Pelican on a Bicycle","SVG spatial reasoning","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-forbidden-city-en', '100001', '0', 'app-eval-forbidden-city', 'en-US', 'Forbidden City 3D Scene Generation', 'Chinese ancient architecture 3D benchmark', 'The Forbidden City prompt tests front-end 3D scene generation: hall proportions, bracket details, snow lighting and interaction performance.', 'Forbidden City and Imperial Palace 3D scenes are a common AI coding test in Chinese communities. Without external assets, a model must build the Hall of Supreme Harmony, marble terrace, eaves and falling snow with Three.js or native WebGL while keeping camera interaction smooth. It scores architectural fidelity, proportional structure, material and lighting, and interaction performance, with per-spec ratings and reviews.', 'Added snow lighting and performance scoring', '["Forbidden City","3D scene generation","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-webdev-arena-en', '100001', '0', 'app-eval-webdev-arena', 'en-US', 'Front-End Arena', 'Pairwise front-end generation benchmark', 'WebDev Arena style pairwise battles score visual fidelity, complete interaction, responsiveness and code quality.', 'Front-End Arena runs blind pairwise battles: the same request goes to two models, and reviewers compare visual fidelity, interaction completeness, responsive adaptation and code quality. Elo-style benchmark scores come from vote counts, with per-spec ratings and reviews.', 'Added responsiveness and accessibility dimensions', '["Front-End Arena","WebDev Arena","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-gaia-en', '100001', '0', 'app-eval-gaia', 'en-US', 'General Assistant Tasks (GAIA)', 'Real-world general assistant benchmark', 'GAIA 466 real-world questions measure multi-step reasoning, tool orchestration, web retrieval and multimodality.', 'GAIA contains 466 real-world questions that are conceptually simple for humans yet hard for current AI, requiring web browsing, multimodal understanding, file handling and multi-step reasoning. It scores task success by multi-step reasoning, tool orchestration, web retrieval and multimodality across BirdCoder, Manus Agent, Claude Code, Codex CLI, Gemini CLI and Cursor Agent, with per-spec ratings and reviews.', 'First release with the 466-question GAIA baseline', '["General Assistant Tasks","GAIA","agent spec","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-safety-en', '100001', '0', 'app-eval-safety', 'en-US', 'Safety Alignment Evaluation', 'Jailbreak and harmful-content refusal benchmark', 'HarmBench and JailbreakBench measure jailbreak resistance, harmful-content refusal, privacy protection and over-refusal.', 'Safety Alignment Evaluation aggregates public safety benchmarks including HarmBench and JailbreakBench, covering jailbreak prompts, harmful requests, privacy extraction and high-risk advice. Over-refusal is reported separately so that refusing everything is not mistaken for safety capability, with per-spec ratings and reviews.', 'Added an over-refusal dimension', '["Safety Alignment","HarmBench","JailbreakBench","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('loc-app-eval-hallucination-en', '100001', '0', 'app-eval-hallucination', 'en-US', 'Factuality and Hallucination Evaluation', 'Factual accuracy and calibration benchmark', 'SimpleQA and TruthfulQA measure factual accuracy, calibration, appropriate abstention and citation traceability.', 'Factuality and Hallucination Evaluation combines OpenAI SimpleQA short factual questions with TruthfulQA common misconceptions. It reports factual accuracy, confidence calibration, appropriate abstention on unknown questions and citation traceability, exposing confident fabrication rather than plain errors, with per-spec ratings and reviews.', 'Added confidence calibration statistics', '["Factuality","SimpleQA","TruthfulQA","AI Model Evaluation"]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
